"""Require the actual BFF/browser test, not a missing or skipped test selection."""
import json
import hashlib
import os
import re
import stat
import subprocess
import sys
from pathlib import Path

PACKAGE = "github.com/eighred/kanz/services/web-bff/internal/server"
TEST = "TestBrowserRendererProductionBundle"
MARKER = "Browser renderer: actual WASM, legacy fallback, missing/tampered/aborted asset and strict CSP controls PASS"


def strict_json(data):
    def pairs(items):
        result = {}
        for key, value in items:
            if key in result: raise ValueError("duplicate JSON key")
            result[key] = value
        return result
    def reject(_): raise ValueError("nonfinite JSON")
    return json.loads(data, object_pairs_hook=pairs, parse_constant=reject)


def validate(data):
    if not data or len(data) > 4 * 1024 * 1024:
        raise ValueError("browser evidence size")
    events = [strict_json(line) for line in data.splitlines()]
    starts, passes, package_passes, markers = 0, 0, 0, 0
    for event in events:
        if not isinstance(event, dict): raise ValueError("invalid event")
        if event.get("Package") != PACKAGE or event.get("Action") in ("fail", "skip"):
            raise ValueError("browser test failed, skipped or wrong package")
        if "(cached)" in event.get("Output", ""): raise ValueError("cached result")
        name, action = event.get("Test"), event.get("Action")
        if name not in (None, TEST):
            raise ValueError("unexpected browser test")
        if name == TEST and action == "run": starts += 1
        if name == TEST and action == "pass":
            if starts != 1: raise ValueError("browser pass without start")
            passes += 1
        if name is None and action == "pass":
            if passes != 1: raise ValueError("package passed before browser")
            package_passes += 1
        if name == TEST and event.get("Output", "").strip() == MARKER: markers += 1
    if (starts, passes, package_passes, markers) != (1, 1, 1, 1):
        raise ValueError("browser proof incomplete")


INPUTS = ("kanz-rs/Cargo.toml", "kanz-rs/Cargo.lock", "kanz-rs/rust-toolchain.toml",
          "kanz-rs/crates/browser-render/Cargo.toml", "kanz-rs/crates/browser-render/src/lib.rs",
          "kanz-web/scripts/build-renderer.mjs", "kanz-web/scripts/build-renderer.test.mjs", "kanz-web/.nvmrc")


def digest(data): return hashlib.sha256(data).hexdigest()


def descriptor(entry, module, identity, source_hashes):
    match = re.fullmatch(r"// Generated by the shared pinned recipe.\nimport url from './browser-render\.([0-9a-f]{64})\.wasm\?url&no-inline'\nexport const rendererAsset = (.+) as const\nexport \{ url \}\n", entry.decode("utf-8").replace("\r\n", "\n"))
    if not match: raise ValueError("asset entry shape")
    value = strict_json(match[2])
    if set(value) != {"format", "abi", "source", "tree", "sourceKind", "run", "attempt", "sources", "moduleSHA256", "moduleBytes", "maxMemoryBytes"}:
        raise ValueError("descriptor fields")
    if (value["format"] != "kanz-browser-render-asset-v1" or type(value["abi"]) is not int or value["abi"] != 1
            or value["sourceKind"] != "committed-ci" or value["maxMemoryBytes"] != 2097152
            or value["sources"] != source_hashes or set(source_hashes) != set(INPUTS)):
        raise ValueError("descriptor contract")
    for key in ("source", "tree", "run", "attempt"):
        if value[key] != identity[key]: raise ValueError("stale source or run")
    if (not 0 < len(module) <= 2097152 or not module.startswith(b"\x00asm\x01\x00\x00\x00")
            or type(value["moduleBytes"]) is not int or value["moduleBytes"] != len(module)
            or value["moduleSHA256"] != digest(module) or match[1] != digest(module)):
        raise ValueError("module identity")
    return value


def read_file(path, limit):
    # CI runs Linux; do not silently lose file-safety guarantees on other hosts.
    if sys.platform != "linux" or not hasattr(os, "O_NOFOLLOW") or not hasattr(os, "O_NONBLOCK"):
        raise ValueError("Linux file reader required")
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
    try:
        before = os.fstat(fd)
        if not stat.S_ISREG(before.st_mode) or before.st_nlink != 1 or not 0 < before.st_size <= limit:
            raise ValueError("evidence file bounds")
        with os.fdopen(fd, "rb", closefd=False) as handle: data = handle.read(limit + 1)
        after = os.fstat(fd)
        fields = ("st_dev", "st_ino", "st_mode", "st_nlink", "st_size", "st_mtime_ns", "st_ctime_ns")
        if len(data) != before.st_size or any(getattr(before, k) != getattr(after, k) for k in fields):
            raise ValueError("evidence changed")
        return data
    finally: os.close(fd)


def qualify(stream, entry, module, identity, source_hashes):
    validate(stream)
    value = descriptor(entry, module, identity, source_hashes)
    return {"format": "kanz-browser-render-proof-v1", **identity,
            "streamSHA256": digest(stream), "descriptorSHA256": digest(entry),
            "moduleSHA256": value["moduleSHA256"], "moduleBytes": len(module),
            "cases": ["ready", "missing", "tampered", "held", "old-csp"], "passed": True}


def main():
    if len(sys.argv) != 3 or os.environ.get("GITHUB_ACTIONS") != "true": raise ValueError("CI proof arguments")
    root = Path(__file__).resolve().parents[2]
    def git(*args):
        return subprocess.run(["git", *args], cwd=root, check=True, stdout=subprocess.PIPE,
                              stderr=subprocess.DEVNULL, timeout=15).stdout
    identity = {"source": git("rev-parse", "HEAD").decode().strip(),
                "tree": git("rev-parse", "HEAD^{tree}").decode().strip(),
                "run": os.environ.get("GITHUB_RUN_ID"), "attempt": os.environ.get("GITHUB_RUN_ATTEMPT")}
    if (identity["source"] != os.environ.get("GITHUB_SHA")
            or not all(re.fullmatch(r"[0-9a-f]{40}", identity[k]) for k in ("source", "tree"))
            or not all(isinstance(identity[k], str) and re.fullmatch(r"[1-9][0-9]{0,19}", identity[k]) for k in ("run", "attempt"))):
        raise ValueError("CI identity")
    hashes = {}
    for name in INPUTS:
        current = read_file(root / name, 4194304)
        if current != git("show", "HEAD:" + name): raise ValueError("uncommitted build input")
        hashes[name] = digest(current)
    modules = list((root / "kanz-web/dist/assets").glob("*.wasm"))
    if len(modules) != 1: raise ValueError("module inventory")
    result = qualify(read_file(Path(sys.argv[1]), 4194304),
                     read_file(root / "kanz-web/src/generated/browser-render.ts", 65536),
                     read_file(modules[0], 2097152), identity, hashes)
    with open(sys.argv[2], "x", encoding="utf-8") as target:
        json.dump(result, target, sort_keys=True); target.write("\n")
    print("Actual BFF/WASM/Chromium five-case source-bound proof accepted")


if __name__ == "__main__":
    try: main()
    except (ValueError, OSError, subprocess.SubprocessError):
        raise SystemExit("Browser rendering proof refused")
